class AsyncUserPasswordResource(AsyncResource):
    """Operations of `client.user.password`."""

    async def change(
        self,
        *,
        old_password: str,
        new_password: str,
        mfa_secret: str | None = None,
        **options: Unpack[RequestOptions],
    ) -> UserTokenPair:
        """Change the password and get new tokens.

        The previous tokens stop working; store the returned pair. Errors: `BAD_CREDENTIALS` (wrong
        old password), `BAD_REQUEST` with `fields[].fieldName = newPassword` and message
        `INVALID_PASSWORD` (weak new password), `INVALID_CODE` (2FA code missing or wrong).

        Args:
            old_password: `oldPassword` body field.
            new_password: 10-30 characters with a lowercase and an uppercase letter.
            mfa_secret: Current TOTP code when 2FA is enabled (the web app sends an empty string
                otherwise).
            **options: Per-request options, see `RequestOptions`.

        Note:
            Experimental: the endpoint may change or disappear without notice. Reconstructed from
            the Whitebird web application; fields may be missing.

        Returns:
            The response as `UserTokenPair`.
        """
        return await self._engine.request(
            "auth",
            "POST",
            "/api/v1/user/password/change-and-reauthorize",
            json={
                "oldPassword": old_password,
                "newPassword": new_password,
                "mfaSecret": mfa_secret,
            },
            cast_to=UserTokenPair,
            options=options,
        )

    async def send_reset_link(
        self,
        *,
        email: str,
        **options: Unpack[RequestOptions],
    ) -> None:
        """Email a password reset link.

        The link carries the `token` for `reset`.

        Public endpoint: works without credentials.

        Args:
            email: `email` query parameter.
            **options: Per-request options, see `RequestOptions`.

        Note:
            Reconstructed from the Whitebird web application; fields may be missing.
        """
        await self._engine.request(
            "auth",
            "GET",
            "/api/v1/user/password/recovery/send",
            params={"email": email},
            authenticated=False,
            options=options,
        )

    async def reset(
        self,
        *,
        token: str,
        new_password: str,
        repeated_password: str,
        mfa_secret: str | None = None,
        **options: Unpack[RequestOptions],
    ) -> None:
        """Set a new password with a reset token.

        Errors: `INVALID_CODE` with message `Secret must not be empty` (2FA code required), `Invalid
        mfa code`, or `Code doesn't exist` (token already used); `EXPIRED_CODE`.

        Public endpoint: works without credentials.

        Args:
            token: Token from the reset link.
            new_password: `newPassword` body field.
            repeated_password: `repeatedPassword` body field.
            mfa_secret: Current TOTP code when 2FA is enabled.
            **options: Per-request options, see `RequestOptions`.

        Note:
            Reconstructed from the Whitebird web application; fields may be missing.
        """
        await self._engine.request(
            "auth",
            "POST",
            "/api/v1/user/password/recovery",
            json={
                "token": token,
                "newPassword": new_password,
                "repeatedPassword": repeated_password,
                "mfaSecret": mfa_secret,
            },
            authenticated=False,
            options=options,
        )


class AsyncUserPhoneResource(AsyncResource):
    """Operations of `client.user.phone`."""

    async def set_notifications(
        self,
        *,
        enabled: bool,
        **options: Unpack[RequestOptions],
    ) -> None:
        """Turn SMS notifications on or off.

        Args:
            enabled: `enabled` body field.
            **options: Per-request options, see `RequestOptions`.

        Note:
            Reconstructed from the Whitebird web application; fields may be missing.
        """
        await self._engine.request(
            "auth",
            "PUT",
            "/api/v1/user/phone",
            json={"enabled": enabled},
            options=options,
        )

    async def change(
        self,
        *,
        country_code: str,
        phone_number: str,
        mfa_secret: str | None = None,
        recaptcha: str | None = None,
        **options: Unpack[RequestOptions],
    ) -> UserPhoneChangeResult:
        """Change the phone number without SMS confirmation.

        Used for countries that do not require SMS confirmation of the new number (the web app uses
        `send_change_code` / `verify_change_code` for the others). With 2FA enabled the first call
        without `mfaSecret` is refused with `INVALID_CODE` / `Secret must not be empty`. Errors:
        `INVALID_RECAPTCHA`, `INVALID_CODE` / `Code has been sent. Try again later`,
        `PHONE_NUMBER_CANNOT_BE_CHANGED`, `PHONE_NUMBER_NOT_AVAILABLE`, `USER_EXISTS`.

        Args:
            country_code: ISO 3166-1 alpha-2 country of the number.
            phone_number: `phoneNumber` body field.
            mfa_secret: Current TOTP code when 2FA is enabled.
            recaptcha: Google reCAPTCHA v3 token (web action `SETTINGS_CHANGE_PHONE`).
            **options: Per-request options, see `RequestOptions`.

        Note:
            Experimental: the endpoint may change or disappear without notice. Reconstructed from
            the Whitebird web application; fields may be missing.

        Returns:
            The response as `UserPhoneChangeResult`.
        """
        return await self._engine.request(
            "auth",
            "POST",
            "/api/v1/user/phone/phone-number-changed/update",
            json={
                "countryCode": country_code,
                "phoneNumber": phone_number,
                "mfaSecret": mfa_secret,
            },
            headers={"recaptcha": recaptcha},
            cast_to=UserPhoneChangeResult,
            options=options,
        )

    async def send_change_code(
        self,
        *,
        country_code: str,
        phone_number: str,
        mfa_secret: str | None = None,
        recaptcha: str | None = None,
        **options: Unpack[RequestOptions],
    ) -> Any:
        """Send an SMS code to a new phone number.

        First step of a phone change that needs SMS confirmation; finish with `verify_change_code`.
        Same 2FA handling and errors as `change`, plus `SMS_SENDING_ERROR`, `SMS_CODE_ERROR`
        (`subStatus` `TOO_MANY_ATTEMPTS` = daily limit) and `SMS_VERIFICATION_NOT_AVAILABLE`.

        Args:
            country_code: ISO 3166-1 alpha-2 country of the number.
            phone_number: `phoneNumber` body field.
            mfa_secret: Current TOTP code when 2FA is enabled.
            recaptcha: Google reCAPTCHA v3 token (web action `SETTINGS_CHANGE_PHONE` or
                `SETTINGS_CHANGE_PHONE_MFA`).
            **options: Per-request options, see `RequestOptions`.

        Note:
            Experimental: the endpoint may change or disappear without notice. Reconstructed from
            the Whitebird web application; fields may be missing.

        Returns:
            The decoded JSON response.
        """
        return await self._engine.request(
            "auth",
            "POST",
            "/api/v1/user/phone/phone-number-changed/send-code",
            json={
                "countryCode": country_code,
                "phoneNumber": phone_number,
                "mfaSecret": mfa_secret,
            },
            headers={"recaptcha": recaptcha},
            options=options,
        )

    async def verify_change_code(
        self,
        *,
        code: str,
        phone_number: str,
        **options: Unpack[RequestOptions],
    ) -> UserPhoneChangeResult:
        """Confirm a new phone number with the SMS code.

        Wrong codes answer `INVALID_CODE`, `INVALID_SMS_CODE` or `BAD_REQUEST`.

        Args:
            code: `code` body field.
            phone_number: `phoneNumber` body field.
            **options: Per-request options, see `RequestOptions`.

        Note:
            Experimental: the endpoint may change or disappear without notice. Reconstructed from
            the Whitebird web application; fields may be missing.

        Returns:
            The response as `UserPhoneChangeResult`.
        """
        return await self._engine.request(
            "auth",
            "POST",
            "/api/v1/user/phone/phone-number-changed/verify-code",
            json={"code": code, "phoneNumber": phone_number},
            cast_to=UserPhoneChangeResult,
            options=options,
        )

    async def send_confirmation_code(
        self,
        **options: Unpack[RequestOptions],
    ) -> None:
        """Send an SMS code to confirm the current phone number.

        The web app asks for it before an operation when the exchange client profile has
        `phoneConfirmationRequired` and the number belongs to a country that requires confirmation.
        (An API error `PHONE_CONFIRMATION_REQUIRED` is instead shown as "contact support".) The web
        app sends an empty JSON object. Errors `SMS_SENDING_ERROR`, `SMS_CODE_ERROR` (`subStatus`
        `TOO_MANY_ATTEMPTS`, `TOO_SOON`).

        Args:
            **options: Per-request options, see `RequestOptions`.

        Note:
            Reconstructed from the Whitebird web application; fields may be missing.
        """
        await self._engine.request(
            "auth",
            "POST",
            "/api/v1/user/phone/phone-confirmation/send-code",
            options=options,
        )

    async def verify_confirmation_code(
        self,
        *,
        code: str,
        **options: Unpack[RequestOptions],
    ) -> None:
        """Confirm the current phone number with the SMS code.

        Wrong codes answer `INVALID_SMS_CODE`; `SMS_VERIFICATION_FAILED` means the confirmation is
        blocked.

        Args:
            code: `code` body field.
            **options: Per-request options, see `RequestOptions`.

        Note:
            Reconstructed from the Whitebird web application; fields may be missing.
        """
        await self._engine.request(
            "auth",
            "POST",
            "/api/v1/user/phone/phone-confirmation/verify-code",
            json={"code": code},
            options=options,
        )
